package com.dreamseekers;

import com.dreamseekers.skill.*;
import com.dreamseekers.unit.*;
import com.mojang.authlib.GameProfile;
import com.solegendary.reignofnether.player.*;
import com.solegendary.reignofnether.registrars.*;
import com.solegendary.reignofnether.resources.*;
import com.solegendary.reignofnether.unit.*;
import com.solegendary.reignofnether.unit.interfaces.*;
import net.minecraft.core.BlockPos;
import net.minecraft.gametest.framework.*;
import net.minecraft.nbt.*;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.ai.attributes.*;
import net.minecraft.world.entity.projectile.Arrow;
import net.minecraft.world.level.ChunkPos;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.phys.*;
import net.minecraftforge.common.util.FakePlayerFactory;
import net.minecraftforge.gametest.*;
import java.io.File;
import java.util.*;

/** A real two-process ordinary world save; the manifest contains expectations, never serialized entity reconstruction. */
@GameTestHolder("dreamseekers_bone_mark_restart")
@PrefixGameTestTemplate(false)
public final class BoneMarkSkillRestartGameTests {
    private static final String OWNER="BoneMarkRestart_Owner",ENEMY="BoneMarkRestart_Enemy";
    private static final BlockPos ORIGIN=new BlockPos(49152,90,49152);
    private static final File MANIFEST=new File("bone-mark-skill-restart-expectations.nbt");
    private static final UUID PERMANENT=UUID.fromString("c226c025-a152-4a52-b76a-5a20b161c258");
    private static final List<String> KEYS=List.of("spentCaster","markedTarget","unusedCaster","freshTarget","ordinaryShooter");
    @GameTest(template="unit_isolation_arena",batch="dreamseekers_bone_mark_restart",timeoutTicks=1500)
    public static void ordinaryRestartKeepsPaidCooldownClearsMarkAndDoesNotReauthorizeSavedArrow(GameTestHelper h) throws Exception {
        switch(System.getProperty("dreamseekers.bone.mark.test.phase","")){case "prepare"->prepare(h);case "verify"->verify(h);default->throw new IllegalArgumentException("Unknown Bone mark restart phase");}
    }
    private static void prepare(GameTestHelper h){
        var level=h.getLevel();h.assertTrue(!MANIFEST.exists()&&PlayerServerEvents.getRTSPlayer(OWNER)==null,"fresh isolated prepare world");CompoundTag expected=new CompoundTag();expected.putLong("prepareJvmStart",java.lang.management.ManagementFactory.getRuntimeMXBean().getStartTime());List<Long> forced=new ArrayList<>();for(int x=3072;x<=3074;x++)for(int z=3072;z<=3074;z++){long chunk=ChunkPos.asLong(x,z);h.assertTrue(!level.getForcedChunks().contains(chunk),"never adopt another fixture's forced chunks");level.setChunkForced(x,z,true);forced.add(chunk);}expected.putLongArray("forcedChunks",forced);arena(level);register(OWNER);register(ENEMY);
        Map<String,Mob> units=new LinkedHashMap<>();units.put("spentCaster",DreamseekersMod.BONE_WING_UNIT.get().create(level));units.put("markedTarget",EntityRegistrar.ZOMBIE_UNIT.get().create(level));units.put("unusedCaster",DreamseekersMod.BONE_WING_UNIT.get().create(level));units.put("freshTarget",EntityRegistrar.ZOMBIE_UNIT.get().create(level));units.put("ordinaryShooter",EntityRegistrar.SKELETON_UNIT.get().create(level));int[][] positions={{4,2,5},{11,1,5},{4,2,25},{24,1,25},{4,1,40}};
        int index=0;for(var entry:units.entrySet()){Mob e=entry.getValue();Unit u=(Unit)e;u.setOwnerName(entry.getKey().endsWith("Target")?ENEMY:OWNER);u.setScenarioRoleIndex(1701+index);int[] p=positions[index++];move(e,p[0],p[1],p[2]);e.setNoAi(true);if(e.getAttribute(AttributeRegistrar.AGGRO_RANGE.get())!=null)e.getAttribute(AttributeRegistrar.AGGRO_RANGE.get()).setBaseValue(0);if(entry.getKey().endsWith("Target")){e.getAttribute(Attributes.MAX_HEALTH).setBaseValue(1000);e.setHealth(1000);e.getAttribute(Attributes.ARMOR).setBaseValue(0);e.getAttribute(Attributes.ARMOR_TOUGHNESS).setBaseValue(0);e.getAttribute(Attributes.KNOCKBACK_RESISTANCE).setBaseValue(1);e.getAttribute(AttributeRegistrar.RANGED_DAMAGE_RESIST.get()).setBaseValue(0);}h.assertTrue(level.addFreshEntity(e),"real registered fixture enters normal entity storage");expected.putUUID(entry.getKey(),e.getUUID());}
        var shooter=(com.solegendary.reignofnether.unit.units.monsters.SkeletonUnit)units.get("ordinaryShooter");shooter.setupEquipmentAndUpgradesServer();shooter.getAttribute(AttributeRegistrar.ATTACK_DAMAGE.get()).setBaseValue(10);shooter.getAttribute(AttributeRegistrar.CRITICAL_HIT_CHANCE.get()).setBaseValue(0);shooter.getAttribute(AttributeRegistrar.ATTACKS_PER_SECOND.get()).addPermanentModifier(new AttributeModifier(PERMANENT,"permanent restart research",.1,AttributeModifier.Operation.ADDITION));Arrow[] old={null};
        h.startSequence().thenWaitUntil(()->{for(Mob e:units.values())h.assertTrue(e.tickCount>3&&level.getEntity(e.getId())==e&&level.getEntity(e.getUUID())==e,"actual published fixture before input");})
          .thenExecute(()->{ledger(h);System.out.println("BONE_MARK_RESTART_PREPARE_READY testTick="+h.getTick()+" entityTicks="+units.values().stream().map(e->e.getId()+":"+e.tickCount).toList());var source=(BoneWingUnit)units.get("spentCaster");h.assertTrue(cast(level,source,units.get("markedTarget"))==SkillResult.SUCCESS,"real mark before ordinary save");move(units.get("markedTarget"),24,1,5);h.assertTrue(CoordinatedMark.ticksRemaining(units.get("markedTarget"),OWNER)>0,"mark is not range tethered after cast");shooter.performUnitRangedAttack(units.get("freshTarget"),1);})
          .thenWaitUntil(()->{for(Entity e:level.getAllEntities())if(e instanceof Arrow arrow&&arrow.getOwner()==shooter){old[0]=arrow;break;}h.assertTrue(old[0]!=null&&level.getEntity(old[0].getUUID())==old[0],"actual native factory arrow normally published");})
          .thenExecute(()->{Arrow arrow=old[0];move(arrow,22,4,25);arrow.setDeltaMovement(Vec3.ZERO);arrow.setNoGravity(true);expected.putUUID("savedArrow",arrow.getUUID());expected.putLong("snapshotGameTime",level.getGameTime());h.assertTrue(CoordinatedMark.ticksRemaining(units.get("markedTarget"),OWNER)>0,"snapshot contains a live short mark, not already expired fixture");for(var entry:units.entrySet()){Mob e=entry.getValue();Unit u=(Unit)e;CompoundTag saved=new CompoundTag();saved.putFloat("health",e.getHealth());saved.putInt("scenario",u.getScenarioRoleIndex());saved.putString("owner",u.getOwnerName());saved.putDouble("baseAPS",e.getAttribute(AttributeRegistrar.ATTACKS_PER_SECOND.get()).getBaseValue());if(e instanceof SkillUnit skill){saved.putLong("revision",skill.rts().skills().revision());saved.putInt("cooldown",skill.rts().skills().cooldownTicks(UnitSkill.COORDINATED_MARK));}expected.put(entry.getKey()+"State",saved);}ledger(h);try{NbtIo.writeCompressed(expected,MANIFEST);}catch(Exception e){throw new RuntimeException(e);}System.out.println("DREAMSEEKERS_BONE_MARK_RESTART_PREPARED gameTime="+level.getGameTime()+" markTicks="+CoordinatedMark.ticksRemaining(units.get("markedTarget"),OWNER)+" cooldown="+((BoneWingUnit)units.get("spentCaster")).rts().skills().cooldownTicks(UnitSkill.COORDINATED_MARK)+" savedArrow="+arrow.getUUID());}).thenSucceed();
    }
    private static void verify(GameTestHelper h) throws Exception {
        var level=h.getLevel();h.assertTrue(MANIFEST.isFile(),"prepare manifest exists");CompoundTag expected=NbtIo.readCompressed(MANIFEST);h.assertTrue(expected.getLong("prepareJvmStart")!=java.lang.management.ManagementFactory.getRuntimeMXBean().getStartTime(),"actual second JVM, not same-process NBT imitation");for(long packed:expected.getLongArray("forcedChunks")){h.assertTrue(level.getForcedChunks().contains(packed),"ordinary world save restored forced chunks");ChunkPos c=new ChunkPos(packed);level.getChunk(c.x,c.z);}Map<String,Mob> units=new LinkedHashMap<>();Arrow[] old={null};
        h.startSequence().thenWaitUntil(()->{for(String key:KEYS){Entity e=level.getEntity(expected.getUUID(key));h.assertTrue(e instanceof Mob&&e instanceof Unit&&e.tickCount>3&&level.getEntity(e.getId())==e,"normal original UUID restoration: "+key);}Entity arrow=level.getEntity(expected.getUUID("savedArrow"));h.assertTrue(arrow instanceof Arrow&&arrow.tickCount>3,"saved real physical projectile normally restored");})
          .thenExecute(()->{ledger(h);System.out.println("BONE_MARK_RESTART_VERIFY_READY testTick="+h.getTick());for(String key:KEYS){Mob e=(Mob)level.getEntity(expected.getUUID(key));units.put(key,e);e.setNoAi(true);Unit u=(Unit)e;CompoundTag saved=expected.getCompound(key+"State");h.assertTrue(u.getOwnerName().equals(saved.getString("owner"))&&u.getScenarioRoleIndex()==saved.getInt("scenario"),"normal owner/scenario retained: "+key);close(h,e.getHealth(),saved.getFloat("health"),"no replay or unintended normal idle attack before verify: "+key);h.assertTrue(UnitServerEvents.getAllUnits().stream().filter(v->v.getUUID().equals(e.getUUID())).count()==1,"exactly one original UUID in roster: "+key);h.assertTrue(CoordinatedMark.ticksRemaining(e,OWNER)==0,"short mark not restored: "+key);close(h,e.getAttribute(AttributeRegistrar.ATTACKS_PER_SECOND.get()).getBaseValue(),saved.getDouble("baseAPS"),"base APS retained");if(e instanceof SkillUnit skill){int remaining=(int)Math.max(0,expected.getLong("snapshotGameTime")+saved.getInt("cooldown")-level.getGameTime());h.assertTrue(skill.rts().skills().cooldownTicks(UnitSkill.COORDINATED_MARK)==remaining,"absolute spent cooldown neither refunded nor reset: "+key);h.assertTrue(skill.rts().skills().revision()>=saved.getLong("revision"),"revision not rewound");}}
            var shooter=(com.solegendary.reignofnether.unit.units.monsters.SkeletonUnit)units.get("ordinaryShooter");h.assertTrue(shooter.getAttribute(AttributeRegistrar.ATTACKS_PER_SECOND.get()).getModifier(PERMANENT)!=null,"permanent research remains");close(h,shooter.getAttributeValue(AttributeRegistrar.ATTACKS_PER_SECOND.get()),expected.getCompound("ordinaryShooterState").getDouble("baseAPS")+.1,"only permanent modifier remains");old[0]=(Arrow)level.getEntity(expected.getUUID("savedArrow"));h.assertTrue(old[0].getOwner()==shooter,"original projectile owner resolved by real world load");var spent=(BoneWingUnit)units.get("spentCaster");move(spent,18,2,5);if(spent.rts().skills().cooldownTicks(UnitSkill.COORDINATED_MARK)>0)h.assertTrue(cast(level,spent,units.get("markedTarget"))!=SkillResult.SUCCESS,"paid live cooldown denies free recast");var fresh=(BoneWingUnit)units.get("unusedCaster");move(fresh,16,2,25);h.assertTrue(cast(level,fresh,units.get("freshTarget"))==SkillResult.SUCCESS,"genuine new post-restart mark succeeds");Mob target=units.get("freshTarget");Vec3 direction=target.position().add(0,target.getBbHeight()/3.0,0).subtract(old[0].position());old[0].setNoGravity(false);old[0].shoot(direction.x,direction.y,direction.z,1.6f,0);})
          .thenIdle(35).thenExecute(()->{Mob target=units.get("freshTarget");close(h,1000-target.getHealth(),10,"restored old native arrow has legal base damage but no replayed ordinary provenance");h.assertTrue(CoordinatedMark.ticksRemaining(target,OWNER)>0,"old-arrow negative control had a real fresh live mark");var shooter=(com.solegendary.reignofnether.unit.units.monsters.SkeletonUnit)units.get("ordinaryShooter");move(shooter,16,1,25);target.invulnerableTime=0;shooter.performUnitRangedAttack(target,1);})
          .thenIdle(35).thenExecute(()->{close(h,1000-units.get("freshTarget").getHealth(),21.2,"new actual factory arrow after restart gains exactly mark12; only old saved shot was denied");ledger(h);System.out.println("DREAMSEEKERS_BONE_MARK_RESTART_UUID_COOLDOWN_NO_REPLAY_ARROW_ORIGIN_PASS elapsedWorldTicks="+(level.getGameTime()-expected.getLong("snapshotGameTime"))+" remaining="+((BoneWingUnit)units.get("spentCaster")).rts().skills().cooldownTicks(UnitSkill.COORDINATED_MARK));for(Mob e:units.values())e.discard();if(old[0]!=null&&!old[0].isRemoved())old[0].discard();PlayerServerEvents.rtsPlayers.removeIf(p->p.name.equals(OWNER)||p.name.equals(ENEMY));ResourcesServerEvents.resourcesList.removeIf(r->r.ownerName.equals(OWNER)||r.ownerName.equals(ENEMY));for(long packed:expected.getLongArray("forcedChunks")){ChunkPos c=new ChunkPos(packed);level.setChunkForced(c.x,c.z,false);}}).thenSucceed();
    }
    private static SkillResult cast(ServerLevel level,BoneWingUnit source,LivingEntity target){return SkillService.request(FakePlayerFactory.get(level,new GameProfile(UUID.nameUUIDFromBytes(OWNER.getBytes(java.nio.charset.StandardCharsets.UTF_8)),OWNER)),new SkillRequest(UnitSkill.COORDINATED_MARK,source.getId(),source.getUUID(),source.rts().skills().revision(),target.getId(),target.getUUID()));}
    private static void register(String owner){PlayerServerEvents.rtsPlayers.add(RTSPlayer.getNewBot(owner,DreamseekersMod.DREAMSEEKERS));ResourcesServerEvents.resourcesList.add(new Resources(owner,123,234,345,456));}
    private static void move(Entity e,int x,int y,int z){e.moveTo(ORIGIN.getX()+x+.5,ORIGIN.getY()+y,ORIGIN.getZ()+z+.5);e.setDeltaMovement(Vec3.ZERO);}
    private static void close(GameTestHelper h,double actual,double expected,String why){h.assertTrue(Math.abs(actual-expected)<.0005,why+": expected="+expected+" actual="+actual);}
    private static void ledger(GameTestHelper h){for(String owner:List.of(OWNER,ENEMY)){var r=ResourcesServerEvents.resourcesList.stream().filter(v->v.ownerName.equals(owner)).findFirst().orElseThrow();System.out.println("BONE_MARK_RESTART_LEDGER gameTime="+h.getLevel().getGameTime()+" owner="+owner+" bank="+r.food+","+r.wood+","+r.ore+","+r.emerald+" pending="+r.foodToAdd+","+r.woodToAdd+","+r.oreToAdd+","+r.emeraldToAdd+" cargo="+UnitServerEvents.getAllUnits().stream().filter(e->e instanceof Unit unit&&unit.getOwnerName().equals(owner)).map(e->e.getUUID()+":"+((Unit)e).getItems()).toList());h.assertTrue(r.food==123&&r.wood==234&&r.ore==345&&r.emerald==456,"skill/restart leaves global ledger unchanged: "+owner+" actual="+r.food+","+r.wood+","+r.ore+","+r.emerald);h.assertTrue(r.foodToAdd==0&&r.woodToAdd==0&&r.oreToAdd==0&&r.emeraldToAdd==0,"fixture has no pending resources to settle: "+owner);for(LivingEntity body:UnitServerEvents.getAllUnits())if(body instanceof Unit unit&&unit.getOwnerName().equals(owner))h.assertTrue(unit.getItems().isEmpty(),"fixture cargo must be empty, never silently cleared: "+body.getUUID()+" "+unit.getItems());}}
    private static void arena(ServerLevel level){for(int x=0;x<46;x++)for(int z=0;z<46;z++)level.setBlock(ORIGIN.offset(x,9,z),Blocks.STONE.defaultBlockState(),2);level.getEntitiesOfClass(net.minecraft.world.entity.item.FallingBlockEntity.class,new AABB(ORIGIN.getX(),ORIGIN.getY()+1,ORIGIN.getZ(),ORIGIN.getX()+46,level.getMaxBuildHeight(),ORIGIN.getZ()+46)).forEach(Entity::discard);for(int x=0;x<46;x++)for(int z=0;z<46;z++){level.setBlock(ORIGIN.offset(x,0,z),Blocks.STONE.defaultBlockState(),2);for(int y=1;y<9;y++)level.setBlock(ORIGIN.offset(x,y,z),(x==0||x==45||z==0||z==45?Blocks.STONE:Blocks.AIR).defaultBlockState(),2);}/* Construction can break grass into seeds worth existing native FOOD. Remove only these unowned arena drops before any fixture unit is spawned; never erase carried inventory. */var drops=level.getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,new AABB(ORIGIN.getX(),ORIGIN.getY(),ORIGIN.getZ(),ORIGIN.getX()+46,ORIGIN.getY()+10,ORIGIN.getZ()+46));System.out.println("BONE_MARK_RESTART_CONSTRUCTION_DROPS_REMOVED count="+drops.size());drops.forEach(Entity::discard);}
}
